const s = $('Extract settings').first().json;
const p = $json;
const strip = h => String(h || '')
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>|<\/(p|li|h\d|tr|div)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
const v = (p.variants && p.variants.nodes && p.variants.nodes[0]) || {};
return { json: {
  product_id: p.id,
  title: p.title,
  brand: p.vendor || '',
  mpn: (p.mpn && p.mpn.value) || '',
  sku: v.sku || '',
  gtin: v.barcode || '',
  category: p.category ? p.category.name : '',
  category_id: p.category ? p.category.id : '',
  spec_url: (p.specUrl && p.specUrl.value) || '',
  description: strip(p.descriptionHtml).slice(0, 3000),
  images: ((p.media && p.media.nodes) || [])
    .map(m => m.preview && m.preview.image && m.preview.image.url).filter(Boolean).slice(0, s.max_images)
} };

const p = $('Build the input').first().json;
const r = $input.first().json;
const MARKERS = ['just a moment', 'verify you are human', 'checking your browser', 'access denied', 'captcha',
  'are you a robot', 'enable javascript and cookies', 'pardon our interruption'];
const looksBlocked = t => t.length < 1500 && MARKERS.some(m => t.slice(0, 3000).toLowerCase().includes(m));
let text = '', status = 'no spec URL';
if (p.spec_url && 'spec_md' in r) {
  // a plain request got through
  const code = Number(r.statusCode) || 0;
  const md = String(r.spec_md || '');
  if (code < 400 && md.length > 300 && !looksBlocked(md)) { text = md; status = 'ok'; }
  else status = code >= 400 ? 'blocked (' + code + ')' : 'empty';
} else if (p.spec_url) {
  // the Firecrawl fallback answered
  const md = String((r.data && r.data.markdown) || '');
  if (md.length > 300 && !looksBlocked(md)) { text = md; status = 'firecrawl'; }
  else status = 'blocked, Firecrawl too';
}
return [{ json: { spec_text: text.slice(0, 60000), spec_status: status } }];

// Runs whether or not the database node is on: a disabled node passes its input through unchanged.
const r = $input.first().json;
const data = r.body && r.body.data;
const lines = [];
if (Number(r.statusCode) === 200 && data && data.FeaturesGroups) {
  for (const g of data.FeaturesGroups) for (const f of (g.Features || [])) {
    const name = f.Feature && f.Feature.Name && f.Feature.Name.Value;
    const val = f.PresentationValue;
    if (name && val !== undefined && val !== null && String(val).trim() !== '') lines.push(name + ': ' + val);
  }
}
return [{ json: { database_text: lines.join('\n') } }];

const p = $('Build the input').first().json;
return p.images.map(u => ({ json: {
  image: 'https://wsrv.nl/?url=' + encodeURIComponent(u) + '&w=768&h=768&fit=contain&cbg=white&output=jpg'
} }));

const s = $('Extract settings').first().json;
const p = $('Build the input').first().json;
const spec = $('Pick the spec text').first().json;
const db = $('Flatten database reply').first().json.database_text || '';
const img = 'image_text' in $input.first().json ? $input.first().json.image_text : '';
const schema = $('Get the schema').all().map(i => i.json).filter(r => r.key)
  .map(r => ({ ...r, allowed: JSON.parse(r.allowed || '[]'), standard_map: JSON.parse(r.standard_map || '{}') }));

const clean = t => String(t || '').split('\n').filter(l => {
  const x = l.trim();
  if (/^!\[/.test(x)) return false;                                        // image lines
  if (/^([*\-+]|\d+\.)?\s*\[[^\]]*\]\([^)]*\)\s*$/.test(x)) return false;  // lines that are only a link
  return true;
}).join('\n').replace(/\]\([^)]*\)/g, ']').replace(/\n{3,}/g, '\n\n');

// Long pages: keep the paragraphs that look like specs, not the first N characters (menus come first)
const SPEC = /(spec|dimension|weight|capacity|material|size|colou?r|power|voltage|watt|battery|resolution|lens|rating|ip6\d|warranty|compatib|includes|in the box|temperature|\d+\s?(mm|cm|m|kg|g|l|ml|oz|w|v|mah|gb|tb|mp)\b)/gi;
const words = schema.flatMap(f => (f.label + ' ' + f.key.replace(/_/g, ' ')).toLowerCase().split(/[^a-z0-9]+/)).filter(w => w.length >= 4);
const focus = (text, budget) => {
  if (text.length <= budget) return text;
  const pieces = [];
  for (const para of text.split(/\n{2,}/)) {
    if (pieces.length && pieces[pieces.length - 1].length + para.length < 700) pieces[pieces.length - 1] += '\n\n' + para;
    else pieces.push(para);
  }
  const scored = pieces.map((t, i) => {
    const low = t.toLowerCase();
    let sc = (t.match(SPEC) || []).length * 3 + (t.match(/\d/g) || []).length / 15;
    for (const w of words) if (low.includes(w)) sc += 2;
    if ((t.match(/\]/g) || []).length > 8) sc -= 5;   // navigation blocks
    return { i, t, sc: sc / Math.max(1, Math.sqrt(t.length / 300)) };
  }).sort((a, b) => b.sc - a.sc);
  const keep = [];
  let used = 0;
  for (const c of scored) {
    if (c.sc <= 0 || used + c.t.length > budget) continue;
    keep.push(c); used += c.t.length;
  }
  return keep.sort((a, b) => a.i - b.i).map(c => c.t).join('\n...\n');
};

// Most trusted first. The product description is SUP, the least trusted.
const sources = [];
if (spec.spec_text) sources.push({ kind: 'spec_page', name: 'manufacturer spec page', text: focus(clean(spec.spec_text), s.max_chars_spec) });
if (db) sources.push({ kind: 'database', name: 'product database', text: focus(db, s.max_chars_other) });
if (img) sources.push({ kind: 'images', name: 'text read from the product images', text: img.slice(0, s.max_chars_other) });
sources.forEach((x, i) => { x.label = 'S' + (i + 1); });
if (p.description) sources.push({ kind: 'description', name: 'supplier description', label: 'SUP', text: p.description });

const fields = schema.map(f => {
  let line = `- ${f.key} (${f.type}${f.unit ? ', ' + f.unit : ''}): ${f.label}`;
  if (f.allowed.length) line += (f.type === 'list' ? '. Any of: ' : '. One of: ') + f.allowed.map(a => JSON.stringify(a)).join(' | ');
  return line;
}).join('\n');

const prompt = `PRODUCT
Brand: ${p.brand}
Model / MPN: ${p.mpn || 'unknown'}
GTIN: ${p.gtin || 'unknown'}
Title: ${p.title}
Category: ${p.category}

SOURCES (the manufacturer spec page and a product database are the most reliable; image text and the supplier description (SUP) are less reliable)
${sources.map(x => `=== ${x.label} (${x.name}) ===\n${x.text}`).join('\n\n') || '(none)'}

FIELDS
${fields}

RULES
1. Use only facts stated in the sources. Never fill a field from what similar products usually have.
2. The title and model number define this exact product. A page may cover a family (other lens sizes, capacities, colours or kits). Report only values for this model.
3. When sources disagree, prefer the spec page, then the product database, then the image text, then SUP.
4. enum fields: return exactly one allowed value, copied verbatim. list fields: return an array of allowed values. If a source clearly states a value that is not in the allowed list, return it as written; a person will review it.
5. number fields: a bare number in the field's unit. Convert if the source uses another unit (40 oz = 1.18 for a field in L).
6. boolean fields: true or false only when a source says so explicitly.
7. Leave a field out when the sources don't state it. Accuracy matters more than coverage.
8. confidence: 0.95 when a spec table or spec line states it for this exact model; 0.8 when stated in prose; 0.6 when you had to interpret or the page covers several models. Leave out anything below 0.6.
9. evidence: a short quote (under 120 characters) copied exactly from the source.

Return only a JSON object: {"values": [{"key": "<field>", "value": <value>, "confidence": <0-1>, "source": "S1", "evidence": "<quote>"}]}`;

return [{ json: { ...p, prompt, schema, field_count: schema.length,
  sources: sources.map(x => ({ label: x.label, kind: x.kind, text: x.text })) } }];

