const s = $('Extract settings').first().json;
const p = $('Build the prompt').first().json;
const r = $json;

// The parser puts the reply in output; fall back to text if it's a raw string
let reply = r.output !== undefined ? r.output : r.text;
if (typeof reply === 'string') {
  const t = reply.replace(/<think>[\s\S]*?<\/think>/g, '').replace(/```(json)?/g, '');
  try { reply = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); } catch (e) { reply = null; }
}
let error = null;
if (r.error) error = 'model call failed: ' + String(r.error.message || r.error).slice(0, 200);
else if (!reply) error = 'unreadable model reply';
else if (!p.schema.length) error = 'no fields set up for category ' + p.category;
const vals = reply && Array.isArray(reply.values) ? reply.values : [];

const squash = t => String(t || '').toLowerCase().replace(/[*_`#|>\[\]•·]/g, ' ').replace(/\s+/g, ' ').trim();
const bySrc = Object.fromEntries(p.sources.map(x => [x.label, x]));
const byKey = Object.fromEntries(p.schema.map(f => [f.key, f]));
const TRUSTED = ['spec_page', 'database'];

const normalise = (f, raw) => {
  const el = String(raw).trim();
  if (f.type === 'enum' || f.type === 'list') {
    const hit = f.allowed.find(a => a.toLowerCase() === el.toLowerCase());
    return hit ? { value: hit, valid: true } : { value: el, valid: f.allowed.length === 0 };
  }
  if (f.type === 'number') {
    const m = el.replace(/,/g, '').match(/-?\d+(?:\.\d+)?/);
    return m ? { value: String(Number(m[0])), valid: true } : { value: el, valid: false };
  }
  if (f.type === 'boolean') {
    const b = { true: 'true', yes: 'true', y: 'true', '1': 'true', false: 'false', no: 'false', n: 'false', '0': 'false' }[el.toLowerCase()];
    return b ? { value: b, valid: true } : { value: el, valid: false };
  }
  return { value: el, valid: el.length > 0 };
};

const rows = [];
for (const v of vals) {
  const f = v && byKey[v.key];
  if (!f || v.value === null || v.value === undefined || v.value === '') continue;
  let conf = Math.max(0, Math.min(1, Number(v.confidence) || 0));
  const src = bySrc[String(v.source || '').toUpperCase()] || null;
  // 1. The quote has to be in the source it names. A quote shortened with "..." passes when every piece is there.
  const pieces = String(v.evidence || '').split(/\.{3}|…/).map(t => squash(t).slice(0, 80)).filter(t => t.length >= 3);
  const hay = src ? squash(src.text) : '';
  if (!(src && pieces.length && pieces.every(t => hay.includes(t)))) conf = Math.min(conf, 0.6);
  // 2. The quote has to carry the value: every word of a text value, or the exact number
  const evTok = new Set(String(v.evidence || '').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean));
  const supports = x => {
    if (typeof x === 'boolean') return true;
    const t = String(x).trim().toLowerCase();
    if (/^-?\d+(\.\d+)?$/.test(t)) return new RegExp('(^|[^0-9.])' + t.replace('.', '\\.') + '([^0-9]|$)').test(String(v.evidence || ''));
    const toks = t.split(/[^a-z0-9]+/).filter(w => w.length >= 2);
    return toks.length > 0 && toks.every(w => evTok.has(w));
  };
  const list = Array.isArray(v.value) ? v.value : [v.value];
  if (!list.every(supports)) conf = Math.min(conf, 0.8);
  // 3. Only the spec page and a product database can skip review
  if (!src || !TRUSTED.includes(src.kind)) conf = Math.min(conf, 0.8);
  // 4. Check each value against the schema
  for (const raw of (f.type === 'list' ? list : list.slice(0, 1))) {
    const n = normalise(f, raw);
    if (!n.value || rows.some(x => x.key === f.key && x.value === n.value)) continue;
    rows.push({ product_id: p.product_id, product_title: p.title, category: p.category, category_id: p.category_id,
      key: f.key, value: n.value, valid: n.valid, confidence: conf, source: src ? src.kind : 'unknown',
      source_url: src && src.kind === 'spec_page' ? p.spec_url : '', evidence: String(v.evidence || '').slice(0, 300),
      push_error: '', reviewed_by: '', slack_channel: '', slack_ts: '' });
  }
}

// 5. The gate. A key goes straight through only when it's unambiguous: one valid value at or above the threshold,
//    or, for a list key, every value valid and confident and no more than max_list_values of them.
for (const k of [...new Set(rows.map(x => x.key))]) {
  const kr = rows.filter(x => x.key === k);
  const ok = kr.every(x => x.valid && x.confidence >= s.auto_approve_confidence)
    && (byKey[k].type === 'list' ? kr.length <= s.max_list_values : kr.length === 1);
  for (const x of kr) {
    x.review_status = ok ? 'auto_approved' : 'pending';
    x.push_status = ok ? 'queued' : 'none';
    if (ok) x.reviewed_by = 'auto';
  }
}

return [{ json: { product_id: p.product_id, title: p.title, rows, error,
  sources: p.sources.map(x => x.label + ' ' + x.kind).join(', '),
  spec_status: $('Pick the spec text').first().json.spec_status,
  values_found: rows.length,
  auto_approved: rows.filter(x => x.review_status === 'auto_approved').length,
  to_review: rows.filter(x => x.review_status === 'pending').length } }];

