const s = $('Review settings').first().json;
const rows = $('Get pending values').all().map(i => i.json).filter(r => r.id);
const schema = $('Get schema for cards').all().map(i => i.json);
const fieldOf = (cat, key) => {
  const f = schema.find(x => x.category === cat && x.key === key) || {};
  return { label: f.label || key, type: f.type || 'text', allowed: JSON.parse(f.allowed || '[]') };
};
const txt = (v, n) => String(v == null ? '' : v).slice(0, n);
const pct = c => Math.round(Number(c) * 100) + '%';
const cards = [];

// 1. Bulk cards: one per category and attribute once enough products are waiting on it.
//    Shared, valid values go on the bulk card; one-offs and off-list values stay on the product cards.
//    List keys always stay on product cards, so all of a product's values for a list key are decided together.
const onBulk = new Set();
const groups = {};
for (const r of rows) {
  if (fieldOf(r.category, r.key).type === 'list') continue;
  (groups[r.category + '|' + r.key] = groups[r.category + '|' + r.key] || []).push(r);
}
for (const rs of Object.values(groups)) {
  const products = new Set(rs.map(r => r.product_id));
  if (products.size < s.bulk_min_products) continue;
  const f = fieldOf(rs[0].category, rs[0].key);
  const counts = {};
  for (const r of rs) counts[r.value] = (counts[r.value] || 0) + 1;
  const shared = rs.filter(r => r.valid && counts[r.value] > 1);
  if (!shared.length) continue;
  const outliers = rs.filter(r => !shared.includes(r));
  shared.forEach(r => onBulk.add(r.id));
  const lines = Object.entries(counts).sort((a, b) => b[1] - a[1])
    .map(([v, n]) => `• *${txt(v, 60)}* × ${n}` + (shared.some(r => r.value === v) ? '' : '  _(stays on its product card)_'));
  cards.push({ ids: shared.map(r => r.id), text: `${f.label}: ${products.size} ${rs[0].category} to review`, blocks: [
    { type: 'header', text: { type: 'plain_text', text: txt(`${f.label}: ${rs[0].category}`, 150) } },
    { type: 'section', text: { type: 'mrkdwn', text: `${products.size} products, ${Object.keys(counts).length} distinct value${Object.keys(counts).length === 1 ? '' : 's'}\n` + lines.slice(0, 30).join('\n') } },
    ...(outliers.length ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: txt('Check on their product cards: ' +
      outliers.slice(0, 8).map(r => `${r.product_title} (${r.value}${r.valid ? '' : ', not in list'})`).join('; '), 3000) }] }] : []),
    { type: 'actions', elements: [
      { type: 'button', style: 'primary', text: { type: 'plain_text', text: `Approve all ${shared.length}` }, action_id: 'bulk_approve', value: 'bulk' },
      { type: 'button', style: 'danger', text: { type: 'plain_text', text: 'Reject all' }, action_id: 'bulk_reject', value: 'bulk' }
    ] }
  ] });
}

// 2. Product cards: every remaining pending value as an editable input.
//    block_id = field_<key>, so the click comes back with the edits keyed.
const byProduct = {};
for (const r of rows) if (!onBulk.has(r.id)) (byProduct[r.product_id] = byProduct[r.product_id] || []).push(r);
const opt = (v, aiPick) => ({ text: { type: 'plain_text', text: txt(v + (aiPick ? ' (AI pick, not in list)' : ''), 75) }, value: txt(v, 150) });
for (const rs of Object.values(byProduct).sort((a, b) => b.length - a.length).slice(0, s.max_products)) {
  const p = rs[0];
  const byKey = {};
  for (const r of rs) (byKey[r.key] = byKey[r.key] || []).push(r);
  const inputs = Object.entries(byKey).slice(0, 40).map(([key, krs]) => {
    const f = fieldOf(p.category, key);
    const vals = krs.map(r => String(r.value));
    const hint = txt(krs.map(r => `${pct(r.confidence)} ${r.source}${r.valid ? '' : ' (not in list)'}` +
      (r.evidence ? ': "' + txt(r.evidence, 90) + '"' : '')).join(' | '), 150) || ' ';
    const block = { type: 'input', block_id: 'field_' + key, optional: true,
      label: { type: 'plain_text', text: txt(f.label, 2000) }, hint: { type: 'plain_text', text: hint } };
    const action_id = 'edit_' + key;
    if ((f.type === 'enum' || f.type === 'list') && f.allowed.length) {
      const extra = vals.filter(v => !f.allowed.some(a => a.toLowerCase() === v.toLowerCase()));
      const options = [...f.allowed.map(a => opt(a)), ...extra.map(v => opt(v, true))].slice(0, 100);
      const init = vals.map(v => options.find(o => o.value.toLowerCase() === v.toLowerCase())).filter(Boolean);
      block.element = f.type === 'list'
        ? { type: 'multi_static_select', action_id, options, ...(init.length ? { initial_options: init } : {}) }
        : { type: 'static_select', action_id, options, ...(init[0] ? { initial_option: init[0] } : {}) };
    } else if (f.type === 'boolean') {
      block.element = { type: 'static_select', action_id, options: [opt('true'), opt('false')], initial_option: opt(vals[0] === 'true' ? 'true' : 'false') };
    } else {
      block.element = { type: 'plain_text_input', action_id, initial_value: txt(vals.join(', '), 3000) };
    }
    return block;
  });
  const specUrl = rs.map(r => r.source_url).find(Boolean);
  cards.push({ ids: rs.map(r => r.id), text: `Specs to review: ${txt(p.product_title, 200)}`, blocks: [
    { type: 'header', text: { type: 'plain_text', text: txt(p.product_title, 150) } },
    { type: 'context', elements: [{ type: 'mrkdwn', text: `${txt(p.category, 80)} · ${rs.length} values to check · hints show confidence, source and the quote` }] },
    { type: 'divider' },
    ...inputs,
    { type: 'actions', elements: [
      { type: 'button', style: 'primary', text: { type: 'plain_text', text: 'Approve' }, action_id: 'attr_approve', value: p.product_id },
      { type: 'button', style: 'danger', text: { type: 'plain_text', text: 'Reject' }, action_id: 'attr_reject', value: p.product_id },
      { type: 'button', text: { type: 'plain_text', text: 'Edit in Shopify' }, action_id: 'link_shopify',
        url: `https://admin.shopify.com/store/${s.store_handle}/products/${String(p.product_id).split('/').pop()}` },
      ...(specUrl ? [{ type: 'button', text: { type: 'plain_text', text: 'Spec page' }, action_id: 'link_spec', url: txt(specUrl, 3000) }] : [])
    ] }
  ] });
}
return cards.map(c => ({ json: c }));

const cards = $('Build the cards').all();
return $input.all().flatMap((it, i) => it.json.ok
  ? cards[i].json.ids.map(id => ({ json: { id, slack_channel: it.json.channel, slack_ts: it.json.ts } }))
  : []);

const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
if (Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) > 300) throw new Error('Stale request');
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || ''; // no URLSearchParams in the Code node
const b = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' ')));
const a = b.actions[0];
// The card's inputs come back in state.values, keyed by block_id field_<key>
const edits = {};
for (const [blockId, inputs] of Object.entries((b.state && b.state.values) || {})) {
  if (!blockId.startsWith('field_')) continue;
  const el = Object.values(inputs)[0] || {};
  const key = blockId.slice(6);
  if (el.type === 'multi_static_select') edits[key] = (el.selected_options || []).map(o => o.value);
  else if (el.type === 'static_select') { if (el.selected_option) edits[key] = el.selected_option.value; }
  else if (el.type === 'plain_text_input') { if (el.value != null) edits[key] = el.value; }
}
const head = (b.message.blocks || [])[0];
return [{ json: { base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'],
  action: a.action_id, product_id: a.value || '', user: b.user.username, channel: b.channel.id, ts: b.message.ts,
  title: head && head.text ? head.text.text : 'Specs', edits } }];

const click = $('Read the click').first().json;
const rows = $('Get the card values').all().map(i => i.json).filter(r => r.id);
const edits = click.edits || {};   // bulk cards have no inputs, so no edits
const out = [];
const byKey = {};
for (const r of rows) (byKey[r.product_id + '|' + r.key] = byKey[r.product_id + '|' + r.key] || []).push(r);
for (const rs of Object.values(byKey)) {
  const base = rs[0];
  const proposed = rs.map(r => String(r.value));
  let chosen = edits[base.key];
  if (chosen === undefined) chosen = proposed;                                 // no input for this key: approve as proposed
  else if (typeof chosen === 'string') chosen = rs.length > 1 ? chosen.split(',') : [chosen];   // a text box holding several values
  chosen = chosen.map(v => String(v).trim()).filter(Boolean);
  for (const r of rs) {
    const { id, createdAt, updatedAt, ...row } = r;   // the table's own columns aren't written back
    const keep = chosen.some(v => v.toLowerCase() === String(r.value).toLowerCase());
    out.push({ json: { ...row, review_status: keep ? 'approved' : 'rejected', push_status: keep ? 'queued' : 'none', reviewed_by: click.user } });
  }
  for (const v of chosen) if (!proposed.some(x => x.toLowerCase() === v.toLowerCase()))
    out.push({ json: { product_id: base.product_id, product_title: base.product_title, category: base.category, category_id: base.category_id,
      key: base.key, value: v, confidence: 1, source: 'reviewer', source_url: '', evidence: 'Edited in Slack by ' + click.user,
      valid: true, review_status: 'edited', push_status: 'queued', push_error: '', reviewed_by: click.user,
      slack_channel: click.channel, slack_ts: click.ts } });
}
return out;

