const s = $('Push settings').first().json;
const trig = $('When Executed by Another Workflow');
const only = trig.isExecuted ? String(trig.first().json.product_id || '') : '';
const schema = $('Get schema for push').all().map(i => i.json);
const cache = $('Get value cache').all().map(i => i.json);
const toHandle = t => String(t || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const KEY_OVERRIDE = { color: 'color-pattern' };   // the taxonomy's Color attribute is stored as shopify.color-pattern

const rows = $('Get queued values').all().map(i => i.json).filter(r => r.id && (!only || r.product_id === only));
const byProduct = {};
for (const r of rows) (byProduct[r.product_id] = byProduct[r.product_id] || []).push(r);

const products = Object.entries(byProduct).slice(0, s.max_products).map(([product_id, rs]) => {
  const groups = {};
  for (const r of rs) {
    if (!groups[r.key]) {
      const f = schema.find(x => x.category === r.category && x.key === r.key) || {};
      const std = f.standard ? (KEY_OVERRIDE[toHandle(f.standard)] || toHandle(f.standard)) : '';
      // a category already known not to have this attribute gets the custom write only
      const notHere = !!std && cache.some(c => c.category_id === r.category_id && c.standard_key === std && c.status === 'not_on_category');
      groups[r.key] = { key: r.key, type: f.type || 'text', standard: f.standard || '', standard_key: notHere ? '' : std,
        standard_map: JSON.parse(f.standard_map || '{}'), rows: [] };
    }
    groups[r.key].rows.push(r);
  }
  return { product_id, category_id: rs[0].category_id, groups: Object.values(groups) };
});

// Standard values with no metaobject yet, grouped by category so each category's taxonomy is read once
const known = new Set(cache.filter(c => c.metaobject_gid).map(c => c.standard_key + '|' + String(c.value).toLowerCase()));
const misses = {};
for (const p of products) for (const g of p.groups) {
  if (!g.standard_key) continue;
  for (const r of g.rows) {
    const value = String(r.value);
    if (known.has(g.standard_key + '|' + value.toLowerCase())) continue;
    const m = misses[p.category_id] = misses[p.category_id] || { category_id: p.category_id, values: [] };
    if (!m.values.some(v => v.standard_key === g.standard_key && v.value === value))
      m.values.push({ standard: g.standard, standard_key: g.standard_key, value, taxonomy_name: g.standard_map[value] || value });
  }
}
return [{ json: { products, misses: Object.values(misses) } }];

const s = $('Push settings').first().json;
const token = $('Get Shopify token for Push').first().json.access_token;
const url = `https://${s.store_domain}/admin/api/2026-10/graphql.json`;
const gql = (query, variables) => this.helpers.httpRequest({ method: 'POST', url, json: true,
  headers: { 'X-Shopify-Access-Token': token }, body: { query, variables } });
const READ = `query CategoryAttributes($id: ID!) {
  node(id: $id) {
    ... on TaxonomyCategory {
      attributes(first: 100) {
        nodes { __typename ... on TaxonomyChoiceListAttribute { id name values(first: 250) { nodes { id name } } } }
      }
    }
  }
}`;
const UPSERT = `mutation UpsertValue($handle: MetaobjectHandleInput!, $metaobject: MetaobjectUpsertInput!) {
  metaobjectUpsert(handle: $handle, metaobject: $metaobject) {
    metaobject { id handle }
    userErrors { field message code }
  }
}`;
const toHandle = t => String(t || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const PATTERN_SOLID = 'gid://shopify/TaxonomyValue/2874';   // colour entries also need a pattern
const out = [];
for (const m of $('Plan the push').first().json.misses) {
  const r = await gql(READ, { id: m.category_id });
  const attrs = ((((r.data || {}).node || {}).attributes || {}).nodes || []).filter(a => a.__typename === 'TaxonomyChoiceListAttribute');
  const flagged = new Set();
  for (const v of m.values) {
    const attr = attrs.find(a => a.name.toLowerCase() === v.standard.toLowerCase());
    if (!attr) {
      // this category has no such attribute: remember it, and write the custom metafield only
      if (!flagged.has(v.standard_key)) out.push({ json: { category_id: m.category_id, standard_key: v.standard_key, value: '',
        taxonomy_value_gid: '', metaobject_gid: '', status: 'not_on_category' } });
      flagged.add(v.standard_key);
      continue;
    }
    const tv = attr.values.nodes.find(x => x.name.toLowerCase() === v.taxonomy_name.toLowerCase())
      || attr.values.nodes.find(x => x.name.toLowerCase() === 'other');
    if (!tv) { out.push({ json: { category_id: '', standard_key: v.standard_key, value: v.value, taxonomy_value_gid: '', metaobject_gid: '', status: 'failed: no taxonomy value and no Other' } }); continue; }
    const fields = v.standard_key === 'color-pattern'
      ? [{ key: 'label', value: v.value }, { key: 'color_taxonomy_reference', value: JSON.stringify([tv.id]) }, { key: 'pattern_taxonomy_reference', value: PATTERN_SOLID }]
      : [{ key: 'label', value: v.value }, { key: 'taxonomy_reference', value: tv.id }];
    const u = await gql(UPSERT, { handle: { type: 'shopify--' + v.standard_key, handle: toHandle(v.value) }, metaobject: { fields } });
    const mo = u.data && u.data.metaobjectUpsert;
    const errs = [].concat(u.errors || [], (mo && mo.userErrors) || []).map(e => e.message);
    out.push({ json: { category_id: '', standard_key: v.standard_key, value: v.value, taxonomy_value_gid: tv.id,
      metaobject_gid: mo && mo.metaobject ? mo.metaobject.id : '', status: errs.length ? 'failed: ' + errs.join('; ').slice(0, 200) : 'ok' } });
  }
}
return out;

const s = $('Push settings').first().json;
const plan = $('Plan the push').first().json;
const fresh = $('Resolve standard values').isExecuted ? $('Resolve standard values').all().map(i => i.json) : [];
const cache = [...$('Get value cache').all().map(i => i.json), ...fresh];
const gidFor = (key, value) => (cache.find(c => c.standard_key === key && c.metaobject_gid
  && String(c.value).toLowerCase() === String(value).toLowerCase()) || {}).metaobject_gid;
const notHere = (cat, key) => fresh.some(c => c.category_id === cat && c.standard_key === key && c.status === 'not_on_category');
const TYPE = { enum: 'single_line_text_field', list: 'list.single_line_text_field', number: 'number_decimal', boolean: 'boolean', text: 'single_line_text_field' };
const M = `mutation Push($mf: [MetafieldsSetInput!]!) {
  metafieldsSet(metafields: $mf) {
    metafields { id namespace key }
    userErrors { field message code }
  }
}`;
const units = [];    // one per metafield: { kind, mf, rowIds }
const parked = [];   // rows settled before any request
for (const p of plan.products) {
  for (const g of p.groups) {
    const values = [...new Set(g.rows.map(r => String(r.value)))];
    const ids = g.rows.map(r => r.id);
    const type = TYPE[g.type] || 'single_line_text_field';
    if (!type.startsWith('list.') && values.length > 1) {
      parked.push(...ids.map(id => ({ id, push_status: 'failed', push_error: 'More than one value for a single-value field' })));
      continue;
    }
    units.push({ kind: 'custom', rowIds: ids, mf: { ownerId: p.product_id, namespace: s.namespace, key: g.key, type,
      value: type.startsWith('list.') ? JSON.stringify(values) : values[0] } });
    // the twin: the product's category metafield, when the schema names a standard attribute
    if (g.standard_key && !notHere(p.category_id, g.standard_key)) {
      const gids = values.map(v => gidFor(g.standard_key, v)).filter(Boolean);
      if (gids.length === values.length)
        units.push({ kind: 'standard', rowIds: ids, mf: { ownerId: p.product_id, namespace: 'shopify', key: g.standard_key,
          type: 'list.metaobject_reference', value: JSON.stringify([...new Set(gids)]) } });
      else parked.push(...ids.map(id => ({ id, twin: 'no metaobject for every value yet' })));
    }
  }
}
const out = [];
for (let i = 0; i < units.length; i += 25) {
  const chunk = units.slice(i, i + 25);
  out.push({ json: { query: M, variables: { mf: chunk.map(u => u.mf) }, units: chunk, parked: i === 0 ? parked : [] } });
}
if (!out.length) out.push({ json: { query: M, variables: { mf: [] }, units: [], parked } });
return out;

const s = $('Push settings').first().json;
const token = $('Get Shopify token for Push').first().json.access_token;
const url = `https://${s.store_domain}/admin/api/2026-10/graphql.json`;
const reqs = $('Build the metafields').all().map(i => i.json);
const resps = $input.all().map(i => i.json);
const norm = r => {
  const ms = r && r.data && r.data.metafieldsSet;
  const errs = [].concat((r && r.errors) || [], (ms && ms.userErrors) || []);
  return { written: (ms && ms.metafields) || [], errors: errs.map(e => e.message || JSON.stringify(e)) };
};
const state = {};   // row id -> { custom, twin, error }
const note = (u, ok, msg) => {
  for (const id of u.rowIds) {
    const st = state[id] = state[id] || {};
    if (u.kind === 'custom') { st.custom = ok; if (!ok) st.error = msg; }
    else st.twin = ok ? 'ok' : (/subtype does not match/i.test(msg) ? 'mismatch' : 'failed: ' + msg);
  }
};
for (let i = 0; i < reqs.length; i++) {
  const q = reqs[i];
  for (const p of q.parked) state[p.id] = { ...(state[p.id] || {}), ...(p.push_status ? { custom: false, error: p.push_error } : { twin: 'skipped: ' + p.twin }) };
  if (!q.units.length) continue;
  const b = norm(resps[i]);
  if (b.errors.length === 0 && b.written.length >= q.units.length) { q.units.forEach(u => note(u, true, '')); continue; }
  for (const u of q.units) {
    let ok = false, msg = '';
    try {
      const n = norm(await this.helpers.httpRequest({ method: 'POST', url, json: true,
        headers: { 'X-Shopify-Access-Token': token }, body: { query: q.query, variables: { mf: [u.mf] } } }));
      ok = n.written.length > 0 && n.errors.length === 0;
      msg = n.errors.join('; ');
    } catch (e) { msg = 'HTTP error: ' + (e.message || String(e)); }
    note(u, ok, msg || (ok ? '' : 'Write not confirmed by Shopify'));
  }
}
return Object.entries(state).map(([id, st]) => {
  let push_status, push_error = '';
  if (st.custom === false) { push_status = 'failed'; push_error = st.error || ''; }
  else if (st.twin === 'mismatch') { push_status = 'category_mismatch'; push_error = 'Category has no such attribute; custom metafield written'; }
  else { push_status = 'pushed'; if (st.twin && st.twin !== 'ok') push_error = 'Category metafield ' + st.twin; }
  return { json: { id, push_status, push_error: push_error.slice(0, 300) } };
});
